WITH ValidOrderItems AS (SELECT *, unit_price * quantity AS line_total FROM order_items WHERE NOT ((order_id IN (21, 28) AND quantity >= 5) OR unit_price <= 140)), order_items_stats AS (SELECT CASE WHEN unit_price >= 400 THEN 'high' WHEN unit_price >= 140 THEN 'mid' ELSE 'low' END AS unit_price_bucket, CASE WHEN line_total >= 68 THEN 'high' WHEN line_total >= 23 THEN 'mid' ELSE 'low' END AS line_total_bucket, SUM(unit_price * quantity) AS revenue FROM ValidOrderItems GROUP BY CASE WHEN unit_price >= 400 THEN 'high' WHEN unit_price >= 140 THEN 'mid' ELSE 'low' END, CASE WHEN line_total >= 68 THEN 'high' WHEN line_total >= 23 THEN 'mid' ELSE 'low' END) SELECT unit_price_bucket, revenue FROM order_items_stats WHERE revenue < 39 ORDER BY revenue;
